import org.springframework.web.bind.annotation.SessionAttribute;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class SettingsController {

    /**
     * The sheet's settings as the screen shows them: the clerk limit, the floor, the terms, the late percent and the
     * cap in force on the sheet's today (the clerk limit carries two decimals, or is null for none, the floor carries
     * two decimals, the terms are whole days, the late percent carries two decimals, and the cap carries two decimals,
     * or is null for none); the policy date, null when blank (the sheet's today), and the period numbering from, null
     * when blank (off); the entry date, null when blank (off); the grace days, null when blank (off); the pot, two decimals or null for none; the alert threshold, two decimals or null for off; the parent sheet's id, null for none; the fiscal start month, 1 to 12; the escalation gap in days, null when blank (off); the review SLA in days, null when blank (none); the proof kinds, comma separated, null when blank (none); the default grade, null when blank (A); the mid and high score thresholds, null when blank (none); the score log switch, "on" or null when blank (off); and every value recorded for the dated settings, from which the screen works out the one in
     * force on any date; and the permission matrix as set, by action (an action not listed keeps the standing rule).
     */
    public record SettingsView(String clerkLimit, String floor, int terms, String latePct, LocalDate policyDate,
            LocalDate periodNumberingFrom, LocalDate entryDate, Integer graceDays, String cap, List<DatedSettingView> dated, Map<String, String> permissions,
            String pot, String alertThreshold, String parent, int fiscalStartMonth,
            Integer escalateAfter, Integer reviewSla, String proofKinds, String defaultGrade,
            Integer scoreMid, Integer scoreHigh, String scoreLog) {
        static SettingsView of(Sheet sheet) {
            LocalDate today = sheet.getToday();
            return new SettingsView(sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                    sheet.floorOn(today).toPlainString(), sheet.termsOn(today), sheet.latePctOn(today).toPlainString(),
                    sheet.getPolicyDate(), sheet.getPeriodNumberingFrom(), sheet.getEntryDate(), sheet.getGraceDays(),
                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
                    sheet.getSettings().stream().map(DatedSettingView::of)
                            .sorted(Comparator.comparing(DatedSettingView::key).thenComparing(DatedSettingView::from))
                            .toList(),
                    sheet.getPermissions(), sheet.getPot() == null ? null : sheet.getPot().toPlainString(),
                    sheet.getAlertThreshold() == null ? null : sheet.getAlertThreshold().toPlainString(),
                    sheet.getParentId(), sheet.getFiscalStartMonth(), sheet.getEscalateAfter(),
                    sheet.getReviewSla(), sheet.getProofKinds(), sheet.getDefaultGrade(),
                    sheet.getScoreMid(), sheet.getScoreHigh(), sheet.isScoreLog() ? "on" : null);
        }
    }

    /**
     * One value recorded for a dated setting (clerk-limit, floor, terms, terms-<grade>, grace-<grade>, late-pct, cap,
     * proof-threshold, proof-threshold-<grade>, note-threshold, review-threshold or rounding), in force
     * from its from-date; null for none.
     */
    public record DatedSettingView(String key, LocalDate from, String value) {
        static DatedSettingView of(DatedSetting s) {
            return new DatedSettingView(s.getKey(), s.getFrom(), s.getValue());
        }
    }

    /**
     * The clerk limit as the form submits it: 0.00 or more with up to two decimals, or null for no limit; from the
     * date, or null for the sheet's today.
     */
    public record ClerkLimitForm(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal value,
            LocalDate from) {
    }

    /**
     * The cap as the form submits it: 0.00 or more with up to two decimals, or null for no cap; from the date, or
     * null for the sheet's today.
     */
    public record CapForm(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal value, LocalDate from) {
    }

    /**
     * The proof threshold as the form submits it: 0.00 or more with up to two decimals, or null for none; from the
     * date, or null for the sheet's today.
     */
    public record ProofThresholdForm(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal value,
            LocalDate from) {
    }

    /**
     * The note threshold as the form submits it: 0.00 or more with up to two decimals, or null for none; from the
     * date, or null for the sheet's today.
     */
    public record NoteThresholdForm(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal value,
            LocalDate from) {
    }

    /**
     * The review threshold as the form submits it: 0.00 or more with up to two decimals, or null for none; from the
     * date, or null for the sheet's today.
     */
    public record ReviewThresholdForm(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal value,
            LocalDate from) {
    }

    /**
     * The rounding mode as the form submits it: half-up or half-even, or null (blank) for none; from the date, or null
     * for the sheet's today.
     */
    }

    @PutMapping("/settings/default-grade")
    public SettingsView setDefaultGrade(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody DefaultGradeForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setDefaultGrade(user, sheetId, form.value()));
    }

    @PutMapping("/settings/review-sla")
    public SettingsView setReviewSla(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody ReviewSlaForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setReviewSla(user, sheetId, form.value()));
    }

    @PutMapping("/settings/escalate-after")
    public SettingsView setEscalateAfter(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody EscalateAfterForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setEscalateAfter(user, sheetId, form.value()));
    }

    @PutMapping("/settings/score-mid")
    public SettingsView setScoreMid(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
        sheet.setGraceDays(days);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=grace-days value="
                + (days == null ? "" : days.toString()));
        return saved;
    }

    /**
     * Sets the sheet's review SLA (null for blank: none): a REVIEW claim whose review day (the sheet's today when it
     * went to REVIEW) plus these many days is before the sheet's today is late. Not dated.
     */
    @Transactional
    public Sheet setReviewSla(String by, String sheetId, Integer days) {
        Sheet sheet = sheets.lock(sheetId);
        sheet.setReviewSla(days);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=review-sla value="
                + (days == null ? "" : days.toString()));
        return saved;
    }

    /**
     * Sets the sheet's proof kinds (null for blank: none), each receipt or photo, comma separated: while set, a claim
     * whose due is above its proof threshold needs at least one proof of each before it can be settled or approved.
     * Refused for any other kind. Not dated.
     */
     * the last one so recorded). Not to be saved.
     */
    public Sheet asOf(LocalDate day) {
        Sheet then = new Sheet();
        then.id = id;
        then.createdAt = createdAt;
        then.today = day;
        then.permissions.putAll(permissions);
        then.policyDate = policyDate;
        then.periodNumberingFrom = periodNumberingFrom;
        then.entryDate = entryDate;
        then.graceDays = graceDays;
        then.escalateAfter = escalateAfter;
        then.reviewSla = reviewSla;
        then.scoreMid = scoreMid;
        then.scoreHigh = scoreHigh;
        then.scoreLog = scoreLog;
        then.proofKinds = proofKinds;
        then.defaultGrade = defaultGrade;
        then.pot = pot;
        then.alertThreshold = alertThreshold;
     * listed). Statements, the figures they bound, watches, delegations and settle batches are not copied. Refused
     * unless the user is a steward, and unless the other id was never used.
     */
    @Transactional
    public void cloneSheet(String by, String sheetId, String toSheetId) {
        if (!settings.isSteward(sheetId, by)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can clone the sheet.");
        }
        sheetService.lock(sheetId);
        if (sheetId.equals(toSheetId) || sheets.existsById(toSheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The other sheet must be one never used.");
        }
        claims.flush();
        try {
            jdbc.update("INSERT INTO sheet (id, created_at, today, policy_date, period_numbering_from, entry_date,"
                    + " grace_days, pot, alert_threshold, parent_id, fiscal_start_month, escalate_after, review_sla, proof_kinds,"
                    + " score_mid, score_high, score_log, cloned_from)"
                    + " SELECT ?, CURRENT_TIMESTAMP, today, policy_date, period_numbering_from, entry_date, grace_days, pot,"
                    + " alert_threshold, parent_id, fiscal_start_month, escalate_after, review_sla, proof_kinds, score_mid, score_high, score_log, id"
